        // Second purchase triggers reentrancy during round transition
        vm.prank(player);
        game.buyTickets{value: 0.1 ether}(1);

        // Verify attack was executed
        assertTrue(maliciousPlatform.getAttackStatus(), "Attack should be active");
    }
}
