        uint prizePoolAfter = address(game).balance > 0 ? game.rounds(currentRoundAfter).prizePool : 0;
        uint claimableAfter = game.getClaimable(player);
        uint contractBalanceAfter = address(game).balance;

        console.log("Current round:", currentRoundAfter);
        console.log("Prize pool:", prizePoolAfter);
        console.log("Player claimable:", claimableAfter);
        console.log("Contract balance:", contractBalanceAfter);

        console.log("--- DIFFERENTIAL COMPARISON ---");
        bool roundsChanged = currentRoundAfter != currentRoundBefore;
        bool prizePoolChanged = prizePoolAfter != prizePoolBefore;
        bool claimableChanged = claimableAfter != claimableBefore;
        bool balanceChanged = contractBalanceAfter != (contractBalanceBefore + 0.09 ether);

        // Calculate expected balance change
        uint expectedBalance = contractBalanceBefore + 0.09 ether;
        uint expectedPrizePool = prizePoolBefore + 0.08 ether;

        console.log("[State Changes]");
        console.log("Rounds changed:", roundsChanged ? "YES" : "NO");
        console.log("Prize pool change:", prizePoolChanged ? 
                    string(abi.encodePacked("YES (", Strings.toString(prizePoolBefore), "->", Strings.toString(prizePoolAfter), ")")) : 
                    "NO");
        console.log("Claimable change:", claimableChanged ? 
                    string(abi.encodePacked("YES (", Strings.toString(claimableBefore), "->", Strings.toString(claimableAfter), ")")) : 
                    "NO");
        console.log("Balance change abnormal:", balanceChanged ? 
                    string(abi.encodePacked("YES (actual:", Strings.toString(contractBalanceAfter), "/expected:", Strings.toString(expectedBalance), ")")) : 
                    "NO");
        console.log("");

        // Verify attack status
        assertTrue(maliciousPlatform.getAttackStatus(), "Attack should be active");

        // Final verdict determination
        bool vulnerabilityExists = false;
        string memory reason = "Vulnerability not Exist: State stable after attack";

        if (roundsChanged) {
            vulnerabilityExists = true;
            reason = "Vulnerability Exists: Rounds changed unexpectedly during attack";
        } else if (prizePoolChanged && prizePoolAfter != expectedPrizePool) {
            vulnerabilityExists = true;
            reason = "Vulnerability Exists: Prize pool manipulated (expected 0.08 ether increase)";
        } else if (balanceChanged) {
            vulnerabilityExists = true;
            reason = "Vulnerability Exists: Contract balance changed abnormally";
        } else if (claimableChanged && !roundsChanged) {
            vulnerabilityExists = true;
            reason = "Vulnerability Exists: Claimable amount changed unexpectedly";
        }

        // Print vulnerability verdict
